mapper.select:
SELECT a.id, a.customer_id, a.company_name, a.account_number, a.is_default, a.status, a.bank_name, a.remark, u.name operator_name, a.opttime FROM t_erp_customer_account a LEFT JOIN t_userinfo u ON u.id = a.operator WHERE a.customer_id = #{customerId, jdbcType=CHAR}
AND a.status = #{status}
ORDER BY a.is_default DESC, a.opttime DESC
